// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address funder, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(funder != address(c));
        amount = bound(amount, 1, 1e30);
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        vm.deal(address(this), 1);
        c.withdrawAll();
        // Rule: after the owner withdraws everything, c holds no funds,
        // yet the deposit was recorded by the fallback.
        assertTrue(address(c).balance == 0 && c.depositsCount() >= 1);
    }
}
